-- ==============================================================================
-- MIGRATION 266: FISCALIZAÇÃO — AUTUAÇÃO PELO NÚMERO SEI DO CONTRATO
-- Versão: 20261111000266_fiscalizacao_sei_do_contrato.sql
--
-- Pedido do usuário (11/11/2026): para a autuação, vale o número SEI do contrato (o documento, como na coluna "SEI"
-- da planilha de controle da SFC/CGLIC), não o NUP do processo (08020.017653/2026-49) que a migration 262 passou a
-- exigir. A coluna continua processo_sei (o nome fica por compatibilidade com as telas e RPCs); autuado_em passa a
-- guardar a data do contrato (assinatura).
--
-- 1) fisc_contratos: processo_sei aceita o número do documento SEI (7 a 10 dígitos). Um NUP já gravado à mão continua
--    aceito até alguém corrigir.
-- 2) registrar_processo_fiscalizacao: número do documento SEI do contrato (fisc_sei) e a data do contrato.
-- 3) Carga: SEI do contrato da planilha de 05/11/2026 em 398 contratos (o número que mais aparece nas linhas do
--    contrato; em 5 contratos a planilha traz mais de um). Data = assinatura da planilha ou, sem ela, a do
--    Contratos.gov.br. Só preenche contrato da SFC/CGLIC (ou misto) ainda sem número: não sobrescreve o que o fiscal
--    registrou.
-- ==============================================================================

ALTER TABLE public.fisc_contratos DROP CONSTRAINT IF EXISTS fisc_contratos_sei;
ALTER TABLE public.fisc_contratos ADD CONSTRAINT fisc_contratos_sei CHECK (
  (portaria_sei IS NULL OR portaria_sei ~ '^[0-9]{7,10}$')
  AND (processo_sei IS NULL OR processo_sei ~ '^[0-9]{7,10}$' OR processo_sei ~ '^[0-9]{5}\.[0-9]{6}/[0-9]{4}-[0-9]{2}$')
);
COMMENT ON COLUMN public.fisc_contratos.processo_sei IS 'Número SEI do contrato (documento, 7 a 10 dígitos): vale para a autuação (migration 266). NUP antigo aceito até ser corrigido.';
COMMENT ON COLUMN public.fisc_contratos.autuado_em IS 'Data do contrato (assinatura), registrada com o número SEI do contrato.';

CREATE OR REPLACE FUNCTION public.registrar_processo_fiscalizacao(p_contract_key TEXT, p_processo_sei TEXT, p_autuado_em DATE)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_f    public.fisc_contratos%ROWTYPE;
  v_sei  TEXT := public.fisc_sei(p_processo_sei, 'SEI do contrato');
  v_nome TEXT := left(public.nome_do_usuario_logado(), 200);
BEGIN
  IF public.has_permission('fiscalizacao.manage') IS NOT TRUE THEN
    RAISE EXCEPTION 'UNAUTHORIZED: Sem permissão para registrar a fiscalização.' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_f FROM public.fisc_contratos WHERE contract_key = p_contract_key FOR UPDATE;
  IF NOT FOUND OR v_f.fiscalizacao = 'AREA' THEN
    RAISE EXCEPTION 'NOT_FOUND: Este contrato não está com a SFC/CGLIC.' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_role('admin') AND auth.uid() IS DISTINCT FROM v_f.fiscal_user_id AND auth.uid() IS DISTINCT FROM v_f.substituto_user_id THEN
    RAISE EXCEPTION 'UNAUTHORIZED: Só o fiscal, o substituto ou o coordenador registram o SEI deste contrato.' USING ERRCODE = '42501';
  END IF;
  IF v_sei IS NULL THEN
    RAISE EXCEPTION 'INVALID_PAYLOAD: Informe o número SEI do contrato (ex.: 25410220).' USING ERRCODE = '22023';
  END IF;
  IF p_autuado_em IS NULL OR p_autuado_em > (NOW() AT TIME ZONE 'America/Sao_Paulo')::DATE THEN
    RAISE EXCEPTION 'INVALID_PAYLOAD: Informe a data do contrato (até hoje).' USING ERRCODE = '22023';
  END IF;
  UPDATE public.fisc_contratos
     SET processo_sei = v_sei, autuado_em = p_autuado_em, atualizado_por_nome = v_nome, atualizado_em = NOW()
   WHERE contract_key = p_contract_key;
  RETURN jsonb_build_object('contract_key', p_contract_key, 'processo_sei', v_sei, 'autuado_em', p_autuado_em);
END;
$$;
REVOKE ALL ON FUNCTION public.registrar_processo_fiscalizacao(TEXT, TEXT, DATE) FROM PUBLIC, anon, service_role;
GRANT EXECUTE ON FUNCTION public.registrar_processo_fiscalizacao(TEXT, TEXT, DATE) TO authenticated;

