), alvo AS (
  SELECT p.contract_key, p.sei,
         COALESCE(p.assinatura, (SELECT NULLIF(left(co.registro->'raw'->>'data_assinatura', 10), '')::DATE
                                   FROM public.contratos_oficiais co
                                  WHERE co.contract_key = p.contract_key AND co.registro->'raw'->>'data_assinatura' ~ '^\d{4}-\d{2}-\d{2}'
                                  LIMIT 1)) AS data
    FROM planilha p
)
UPDATE public.fisc_contratos f
   SET processo_sei = a.sei, autuado_em = a.data,
       atualizado_por_nome = 'Carga da planilha (05/11/2026)', atualizado_em = NOW()
  FROM alvo a
 WHERE f.contract_key = a.contract_key
   AND f.fiscalizacao <> 'AREA'
   AND f.processo_sei IS NULL
   AND a.data IS NOT NULL;
